//! One strict-script Test262 case per process; no source rewriting or helper stubs.
use gc_lab::{script::{Engine,ScriptError},Model};
fn quote(s:&str)->String{let mut out=String::from("\"");for c in s.chars(){match c{'"'=>out.push_str("\\\""),'\\'=>out.push_str("\\\\"),'\n'=>out.push_str("\\n"),'\r'=>out.push_str("\\r"),'\t'=>out.push_str("\\t"),c if c.is_control()=>out.push_str(&format!("\\u{:04x}",c as u32)),c=>out.push(c)}}out.push('"');out}
fn main(){let mut args=std::env::args().skip(1);let path=args.next().expect("js_check CASE.js [expected runtime error]");let negative=args.next();let source=std::fs::read_to_string(path).expect("source");let mut e=Engine::new(Model::Indirect,Model::Indirect).unwrap();e.enable_test_harness();let result=e.execute(&format!("\"use strict\";\n{source}"));let assertions=e.assertion_count();e.release_globals();let clean=e.live_objects()==0&&e.metadata_objects()==0&&e.live_roots()==0&&e.charged_bytes()==0;
let(status,reason)=if !clean{("failed","GC cleanup failed".into())}else{match(result,negative){(Err(ScriptError::Syntax(s)),_) =>("unsupported",format!("syntax: {}",s.message)),(Err(ScriptError::Unsupported(s)),_) =>("unsupported",s.into()),(Err(ScriptError::Thrown(ex)),Some(expected))if ex.name.as_deref()==Some(expected.as_str())=>("passed",String::new()),(Ok(()),None)=>("passed",String::new()),(result,expected)=>("failed",format!("{result:?}; expected {expected:?}"))}};
println!("{{\"status\":{},\"reason\":{},\"assertions\":{assertions},\"cleanup\":{clean}}}",quote(status),quote(&reason));std::process::exit(match status{"passed"=>0,"unsupported"=>2,_=>1});}
